    malformed = []
    for row in data['structure_constants']:
        try:
            x, y, z = row['X'], row['Y'], row['Z']
            if x not in parity or y not in parity or z not in parity:
                malformed.append(f"unknown label in {row}")
                continue
            constants[(x, y, z)] += Fraction(row['coeff'])
        except Exception as exc:
            malformed.append(f"bad coefficient in {row}: {exc}")
    # Interpret omitted entries as zero and use each listed orientation as authoritative.
    bracket = defaultdict(Fraction)
    for (x,y,z), c in constants.items():
        bracket[(x,y,z)] += c
    anti_fail = []
    # Test all ordered pairs and output coordinates against graded skew-symmetry.
    for x, y in product(basis, repeat=2):
        for z in basis:
            lhs = bracket[(x,y,z)]
            rhs = -((-1) ** (parity[x] * parity[y])) * bracket[(y,x,z)]
            if lhs != rhs:
                anti_fail.append((x,y,z,lhs,y,x,z,rhs))
                if len(anti_fail) >= 20: break
        if len(anti_fail) >= 20: break
    # Jacobi in cyclic form: (-1)^|x||z|[x,[y,z]] + cyclic = 0.
    jac_fail = []
    for x, y, z in product(basis, repeat=3):
        total = defaultdict(Fraction)
        terms = (
            ((-1) ** (parity[x] * parity[z]), x, y, z),
            ((-1) ** (parity[y] * parity[x]), y, z, x),
            ((-1) ** (parity[z] * parity[y]), z, x, y),
        )
        # terms are signed [outer, [inner1, inner2]]
        for sign, outer, inner1, inner2 in terms:
            for mid in basis:
                inner = bracket[(inner1, inner2, mid)]
                if inner:
                    for out in basis:
                        outer_coeff = bracket[(outer, mid, out)]
                        if outer_coeff:
                            total[out] += sign * inner * outer_coeff
        nonzero = {k:v for k,v in total.items() if v}
        if nonzero:
            jac_fail.append((x,y,z,nonzero))
            if len(jac_fail) >= 20: break
    print(f'n={n} dim={len(basis)} constants={len(data["structure_constants"])} pairs={len(basis)**2} triples={len(basis)**3}')
    print(f'  malformed={len(malformed)} anti_symmetry_failures={len(anti_fail)} jacobi_failures={len(jac_fail)}')
    for item in malformed[:3]: print('  MALFORMED', item)
    for item in anti_fail[:3]: print('  ANTI', item)
    for item in jac_fail[:5]: print('  JACOBI', item)
