         [
             basis.realizations[label].get(word, Fraction())
             for label in labels
         ]
         + [target.get(word, Fraction())]
         for word in words
     ]

     pivot_row = 0
     pivots: list[int] = []
     for column in range(len(labels)):
         selected = next(
             (
                 row
                 for row in range(pivot_row, len(matrix))
                 if matrix[row][column]
             ),
             None,
         )
         if selected is None:
